def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first difference and what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            # Insertion at end
            return ("", s_out[len(s_in):], len(s_in))
        else:
            # Deletion at end  
            return (s_in[len(s_out):], "", len(s_out))

    # For now, let's just return the substring that needs to be replaced
    # This is a simplification for our analysis
    return (s_in[pos], s_out[pos], pos)

